"""Prepare one model's payload and executable capabilities before publication."""
from copy import deepcopy
ENVELOPE = frozenset({'stream', 'stream_options', 'files'})

def injections(request, user, metadata, model, messages, events):
    return {'__request__': request, '__user__': user.model_dump(), '__metadata__': metadata, '__model__': model, '__messages__': messages, '__files__': metadata.get('files', []), '__features__': {}, '__chat_id__': metadata.get('chat_id'), '__message_id__': metadata.get('message_id'), '__session_id__': metadata.get('session_id'), **events}

async def prepare_model(adapter, request, body, user, metadata, state, llm_id, events, target=None):
    identity = deepcopy({key: metadata.get(key) for key in ('chat_id', 'message_id', 'lite_router')})
    if target is None:
        if not llm_id or llm_id == state['router_id']:
            raise ValueError('Configure orchestrator_model_id with a real Router LLM')
        inference = request.app.state.MODELS.get(llm_id)
        if not inference or inference.get('pipe'):
            raise ValueError('Router LLM must exist and must not resolve to a Pipe')
    else:
        llm_id = target
        inference = request.app.state.MODELS.get(target)
    model = await adapter.model(request, target or state['router_id'], user)
    selected = deepcopy(model)
    selected['owned_by'] = inference.get('owned_by')
    meta = model.get('info', {}).get('meta') or {}
    tool_ids = ids(meta.get('toolIds') or []) if target else state['base_tool_ids']
    skill_ids = ids(meta.get('skillIds') or []) if target else ids(state['base_skill_ids'] + [entry['skill_id'] for entry in state['registry'].values()])
    prepare_skill_scope(metadata, state, model['id'], skill_ids)
    draft = {key: deepcopy(value) for key, value in body.items() if key in ENVELOPE}
    draft.update(model=llm_id, messages=[deepcopy(m) for m in state['source'] if m.get('role') != 'system'], metadata=metadata)
    draft = await adapter.prompt_and_params(draft, selected, user, metadata)
    prompt = await manifest(adapter, skill_ids, user, None if target else state['registry'])
    if prompt:
        draft['messages'].insert(0, {'role': 'system', 'content': prompt})
    extra = injections(request, user, metadata, model, draft['messages'], events)
    tools, mcp_instructions = await load_capabilities(adapter, request, tool_ids, user, extra)
    if READERS.intersection(tools):
        raise ValueError('Reserved Skill reader collision: ' + ', '.join(sorted(READERS.intersection(tools))))
    for instruction in mcp_instructions:
        draft['messages'].insert(0, {'role': 'system', 'content': instruction})
    if state['registry'] and (not target):
        if 'lite_delegate' in tools:
            raise ValueError('Reserved delegate Tool collision: lite_delegate; remove the separate delegate Tool from base_tool_ids')
        tools['lite_delegate'] = delegate_tool(adapter, request, user, metadata, state)
    else:
        tools.pop('lite_delegate', None)
    if skill_ids:
        builtins = await adapter.builtins(request, model, {**extra, '__skill_ids__': skill_ids})
        for name in READERS:
            if name not in builtins:
                raise ValueError('Required builtin Skill reader unavailable: ' + name)
            if name in tools:
                raise ValueError('Reserved Skill reader collision: ' + name)
            tools[name] = await scoped_reader(adapter, builtins[name], skill_ids, user, draft['messages'])
    if target:
        history = agent_projection(state, target, set(tools), skill_ids)
    else:
        history = router_projection(state, set(tools), skill_ids)
    systems = [m for m in draft['messages'] if m.get('role') == 'system']
    draft['messages'][:] = systems + history
    draft['tools'] = [{'type': 'function', 'function': tool['spec']} for tool in tools.values()]
    protected = {name: (tool['callable'], deepcopy(tool['spec'])) for name, tool in tools.items() if name in READERS or name == 'lite_delegate'}
    metadata['tools'] = tools
    metadata['model_id'] = model['id']
    metadata['model'] = deepcopy(model)
    if target:
        previous_metadata = getattr(request.state, 'metadata', None)
        request.state.metadata = metadata
        request.scope['lite_handoff_preparing'] = True
        try:
            draft = await adapter.inlets(request, draft, model, extra)
        finally:
            request.scope.pop('lite_handoff_preparing', None)
            request.state.metadata = previous_metadata
    if not isinstance(draft, dict) or not isinstance(draft.get('messages'), list):
        raise ValueError('Destination inlet returned an invalid request')
    final_metadata = draft.get('metadata')
    if not isinstance(final_metadata, dict) or any((final_metadata.get(key) != value for key, value in identity.items())):
        raise ValueError('Destination inlet changed request identity')
    tools = final_metadata.get('tools')
    if not isinstance(tools, dict):
        raise ValueError('Destination inlet returned an invalid Tool registry')
    schemas = [schema.get('function') for schema in draft.get('tools') or [] if isinstance(schema, dict)]
    for name in READERS | {'lite_delegate'}:
        expected = protected.get(name)
        found = tools.get(name)
        public = [schema for schema in schemas if isinstance(schema, dict) and schema.get('name') == name]
        if expected is None:
            if found is not None or public:
                raise ValueError('Destination inlet added a reserved Tool: ' + name)
        elif not isinstance(found, dict) or found.get('callable') is not expected[0] or found.get('spec') != expected[1] or (public != [expected[1]]):
            raise ValueError('Destination inlet replaced a protected Tool: ' + name)
    for name, tool in list(tools.items()):
        tools[name] = await bind_tool_context(adapter, tool, draft['messages'])
    draft['tools'] = [{'type': 'function', 'function': tool['spec']} for tool in tools.values()]
    return (draft, tools)

# Source: owui_adapter
"""All imports of OWUI's internal APIs live behind this versioned boundary."""
from copy import deepcopy
from importlib.metadata import PackageNotFoundError, version
import json

def as_dict(value):
    return value.model_dump() if hasattr(value, 'model_dump') else dict(value or {})

class OWUIAdapter:

    def __init__(self):
        try:
            installed_version = version('open-webui')
        except PackageNotFoundError:
            from open_webui.env import VERSION
            installed_version = VERSION
        if installed_version != '0.12.3':
            raise RuntimeError('Lite Handoff Router requires Open WebUI 0.12.3')

    async def user(self, user_id):
        from open_webui.models.users import Users
        user = await Users.get_user_by_id(user_id)
        if user is None:
            raise ValueError('Execution user is unavailable')
        return user

    async def model(self, request, model_id, user):
        from open_webui.models.models import Models
        from open_webui.utils.models import check_model_access
        row = await Models.get_model_by_id(model_id)
        runtime = request.app.state.MODELS.get(model_id)
        if row is None or not row.is_active or runtime is None:
            raise ValueError(f'Workspace Model "{model_id}" is unavailable or inactive')
        await check_model_access(user, runtime, model_info=row)
        result = deepcopy(runtime)
        result['info'] = as_dict(row)
        return result

    async def skill(self, skill_id, user):
        from open_webui.routers.skills import authorized_skill
        skill = await authorized_skill(skill_id, user)
        if not skill.is_active:
            raise ValueError(f'Skill "{skill_id}" is inactive')
        return as_dict(skill)

    async def tools(self, request, ids, user, extra):
        from open_webui.utils.tools import get_tools
        return await get_tools(request, ids, user, extra)

    async def connect_mcp(self, request, server_id, user, extra):
        from open_webui.utils.tools import connect_mcp_server
        return await connect_mcp_server(request, server_id, user, extra)

    async def mcp_access(self, server_id, user):
        from open_webui.env import ENABLE_TOOL_SERVERS
        from open_webui.models.config import Config
        from open_webui.utils.access_control import has_connection_access
        connections = await Config.get('tool_server.connections', [])
        connection = next((c for c in connections if c.get('type') == 'mcp' and (c.get('info') or {}).get('id') == server_id), None)
        if not ENABLE_TOOL_SERVERS or not connection or (not (connection.get('config') or {}).get('enable')) or (not await has_connection_access(user, connection)):
            raise ValueError('Required MCP connection unavailable or denied: ' + server_id)

    async def builtins(self, request, model, extra):
        from open_webui.utils.tools import get_builtin_tools
        return await get_builtin_tools(request, extra, features={}, model=model)

    async def bind(self, function, extra):
        from open_webui.utils.tools import get_async_tool_function_and_apply_extra_params
        return await get_async_tool_function_and_apply_extra_params(function, extra)

    async def refresh(self, function, extra):
        from open_webui.utils.tools import get_updated_tool_function
        return await get_updated_tool_function(function, extra)

    async def prompt_and_params(self, body, model, user, metadata):
        from open_webui.utils.payload import apply_params_to_form_data, apply_system_prompt_to_body
        params = deepcopy(model.get('info', {}).get('params') or {})
        body = apply_params_to_form_data(body, model, params)
        return await apply_system_prompt_to_body(params.get('system'), body, metadata, user)

    async def inlets(self, request, body, model, extra):
        from open_webui.utils.filter import get_filter_functions, process_filter_functions
        filters = await get_filter_functions(request, model, [])
        body, _ = await process_filter_functions(request=request, filter_context=None, filter_functions=filters, filter_type='inlet', form_data=body, extra_params=extra)
        return body

    async def complete(self, request, body, user):
        from fastapi import HTTPException
        from starlette.responses import Response, StreamingResponse
        from open_webui.models.config import Config
        from open_webui.utils.chat import generate_chat_completion
        if await Config.get('chat.context_compaction.enable', False):
            raise RuntimeError('Lite Handoff Router requires full history: disable chat.context_compaction.enable in OWUI before continuing')
        try:
            response = await generate_chat_completion(request, body, user, bypass_system_prompt=True)
        except HTTPException as error:
            raise RuntimeError(str(error.detail)) from error
        if isinstance(response, Response) and response.status_code >= 400:
            raw = getattr(response, 'body', b'')
            detail = raw.decode(errors='replace') if isinstance(raw, bytes) else str(raw)
            raise RuntimeError(detail or f'Provider HTTP {response.status_code}')
        if isinstance(response, StreamingResponse):
            return response
        if isinstance(response, Response):
            response = json.loads(response.body)
        if response is None or (isinstance(response, dict) and response.get('error')):
            raise RuntimeError(str(response or 'Provider returned no response'))
        return response

